add_action( 'woocommerce_review_order_before_submit', 'perfectpixel_checkout_upsell_box' );

function perfectpixel_checkout_upsell_box() {
	$ids = wp_parse_id_list( '{{upsell_product_ids}}' );
	if ( ! $ids || ! WC()->cart ) {
		return;
	}
	$in_cart = array();
	foreach ( WC()->cart->get_cart() as $item ) {
		$in_cart[] = (int) $item['product_id'];
	}

	$rows = '';
	foreach ( $ids as $id ) {
		$product = wc_get_product( $id );
		if ( ! $product || ! $product->is_purchasable() || ! $product->is_in_stock() || in_array( $id, $in_cart, true ) || ! $product->is_type( 'simple' ) ) {
			continue;
		}
		$rows .= sprintf(
			'<li style="display:flex;justify-content:space-between;align-items:center;gap:1em;margin:.4em 0"><span>%1$s — %2$s</span><a class="button" href="%3$s">%4$s</a></li>',
			esc_html( $product->get_name() ),
			wp_kses_post( $product->get_price_html() ),
			esc_url( add_query_arg( 'add-to-cart', $id, wc_get_checkout_url() ) ),
			esc_html( '{{upsell_button}}' )
		);
	}
	if ( '' !== $rows ) {
		echo '<div class="perfectpixel-checkout-upsell" style="border:1px dashed currentColor;padding:1em;margin:0 0 1em"><strong>' . esc_html( '{{upsell_title}}' ) . '</strong><ul style="list-style:none;margin:.5em 0 0;padding:0">' . $rows . '</ul></div>'; // phpcs:ignore WordPress.Security.EscapeOutput -- Rows escaped above.
	}
}
